import os
from dotenv import load_dotenv
from deepeval import evaluate
from deepeval.test_case import LLMTestCase
from deepeval.metrics import FaithfulnessMetric, AnswerRelevancyMetric

# Load environment variables (DeepEval automatically picks up OPENAI_API_KEY)
load_dotenv()

if not os.getenv("OPENAI_API_KEY"):
    raise ValueError(
        "OPENAI_API_KEY is required in your .env file for DeepEval metrics evaluation.")

# Define a test case simulating your GraphRAG output
# input: User question
# actual_output: The response generated by your GraphRAG pipeline
# retrieval_context: The context fetched from your Neo4j Knowledge Graph
test_case = LLMTestCase(
    input="What equipment or subsidies are offered under the plant protection schemes?",
    actual_output=(
        "Under the Distribution of manually operated Plant Protection Equipment scheme, "
        "farmers are provided financial assistance and subsidies to procure plant protection equipment."
    ),
    retrieval_context=[
        "Scheme 'Distribution of manually operated Plant Protection Equipment' offers subsidies for equipment procurement."
    ]
)

# Initialize DeepEval Metrics using gpt-4o-mini as the judge model
faithfulness_metric = FaithfulnessMetric(
    threshold=0.7,
    model="gpt-4o-mini",
    include_reason=True
)

relevancy_metric = AnswerRelevancyMetric(
    threshold=0.7,
    model="gpt-4o-mini",
    include_reason=True
)


def run_evaluation():
    print("\n🔍 Running DeepEval on Knowledge Graph RAG Pipeline...")

    # Execute evaluation using DeepEval's evaluate function
    evaluate(
        test_cases=[test_case],
        metrics=[faithfulness_metric, relevancy_metric]
    )


if __name__ == "__main__":
    run_evaluation()
